{
  "goal_summary": "该目标旨在培养独立参加机器学习比赛所需的核心能力，涵盖问题定义、数据处理、模型构建、实验评估、结果提交与竞赛策略等环节。能力拆分基于比赛应用场景，不涉及个人现有水平判断。",
  "capabilities": [
    {
      "name": "机器学习基础概念与范式",
      "type": "knowledge",
      "required_level": "understanding",
      "importance": "critical",
      "description": "理解监督学习、无监督学习、分类、回归、聚类、损失函数、过拟合与欠拟合等基本概念，为后续建模与调参提供理论支撑。",
      "concept_type": "concept"
    },
    {
      "name": "比赛任务与评价指标理解",
      "type": "knowledge",
      "required_level": "application",
      "importance": "critical",
      "description": "能够根据比赛说明识别任务类型（分类、回归、排序等），理解官方评价指标（如AUC、F1、RMSE、MAE等）及其优化方向。",
      "concept_type": "concept"
    },
    {
      "name": "数据探索与预处理",
      "type": "application",
      "required_level": "application",
      "importance": "critical",
      "description": "能够对训练集和测试集进行缺失值、异常值、分布、类别不平衡等探索，并执行标准化、归一化、编码、填充等预处理操作。",
      "concept_type": "skill"
    },
    {
      "name": "特征工程",
      "type": "application",
      "required_level": "application",
      "importance": "critical",
      "description": "能够构造、选择、变换特征，包括分箱、交叉、聚合、文本/类别特征编码等，以提升模型表现。",
      "concept_type": "skill"
    },
    {
      "name": "常用机器学习模型应用",
      "type": "application",
      "required_level": "application",
      "importance": "critical",
      "description": "能够调用并训练常见模型（如线性模型、决策树、随机森林、梯度提升树、神经网络等），理解其适用场景与基本参数。",
      "concept_type": "skill"
    },
    {
      "name": "模型评估与验证策略",
      "type": "application",
      "required_level": "application",
      "importance": "critical",
      "description": "能够设计并实施交叉验证、留出法、分层抽样等验证方案，正确计算评价指标，避免数据泄漏。",
      "concept_type": "skill"
    },
    {
      "name": "超参数调优与模型选择",
      "type": "application",
      "required_level": "application",
      "importance": "critical",
      "description": "能够使用网格搜索、随机搜索、贝叶斯优化等方法进行超参数调优，并依据验证结果选择模型。",
      "concept_type": "skill"
    },
    {
      "name": "集成学习与模型融合",
      "type": "application",
      "required_level": "application",
      "importance": "supporting",
      "description": "能够应用Bagging、Boosting、Stacking、Blending等集成方法，或对多个模型结果进行加权融合以提升排名。",
      "concept_type": "skill"
    },
    {
      "name": "深度学习基础与框架使用",
      "type": "application",
      "required_level": "application",
      "importance": "supporting",
      "description": "能够使用至少一种深度学习框架（如PyTorch、TensorFlow）构建、训练和调试简单神经网络，适用于图像、文本或结构化数据比赛。",
      "concept_type": "skill"
    },
    {
      "name": "比赛策略与结果提交",
      "type": "practice",
      "required_level": "application",
      "importance": "critical",
      "description": "能够制定提交策略，包括提交格式、提交频率、排行榜反馈分析、过拟合风险控制，并完成有效提交。",
      "concept_type": "skill"
    },
    {
      "name": "实验管理与可复现性",
      "type": "practice",
      "required_level": "application",
      "importance": "supporting",
      "description": "能够记录实验配置、随机种子、数据版本、模型参数，保证结果可复现，便于迭代优化。",
      "concept_type": "skill"
    },
    {
      "name": "持续学习与问题解决",
      "type": "meta_skill",
      "required_level": "transfer",
      "importance": "supporting",
      "description": "能够在比赛过程中查阅文献、复现方案、分析失败原因并调整方向，独立解决新出现的问题。",
      "concept_type": "skill"
    }
  ],
